            if (left.lenSuff > 0) {
                int c = left.length;
                if (len > 0 && dest.suffG[len - 1] == 1) {
                    dest.suffC[len - 1] += c;
                } else {
                    dest.suffG[len] = 1;
                    dest.suffC[len] = c;
                    len++;
                }
            }
        } else {
            for (int k = 0; k < left.lenSuff; k++) {
                int g = gcd(gRtotal, left.suffG[k]);
                int c = left.suffC[k];
                if (len > 0 && dest.suffG[len - 1] == g) {
                    dest.suffC[len - 1] += c;
                } else {
                    dest.suffG[len] = g;
                    dest.suffC[len] = c;
                    len++;
                }
            }
        }
        dest.lenSuff = len;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
